package l1j.server.server.model.network.core;import java.util.*;import java.nio.*;public class CUserSocket {public final List<byte[]> wires=new ArrayList<>();public boolean shared=true,fail;public boolean isClientConnected(){return true;}public CIOFrame beginDirectFrame(int n){return new CIOFrame(n);}public boolean commitDirectFrame(CIOFrame f){var b=f.writer.data;int n=b.position();b.putShort(0,(short)n);wires.add(Arrays.copyOf(b.array(),n));return true;}public void abortDirectFrame(CIOFrame f){throw new AssertionError("unexpected abort");}public boolean sendAction(int id,int action){CIOFrame f=beginDirectFrame(8);f.buffer().writeC(l1j.server.server.Opcodes.S_ACTION);f.buffer().writeD(id);f.buffer().writeC(action);return commitDirectFrame(f);}}
